class Rectangulo {
    protected int ancho, alto;
    void setAncho(int a) { this.ancho = a; }
    void setAlto(int a) { this.alto = a; }
}
class Cuadrado extends Rectangulo {
    @Override
    void setAncho(int a) { this.ancho = a; this.alto = a; }
    @Override
    void setAlto(int a) { this.ancho = a; this.alto = a; }
}

interface EstrategiaDescuento {
    double calcular(double monto);
}
class DescuentoNavidad implements EstrategiaDescuento {
    public double calcular(double monto) { return monto * 0.9; }
}
class DescuentoBlackFriday implements EstrategiaDescuento {
    public double calcular(double monto) { return monto * 0.7; }
}
class Carrito {
    private EstrategiaDescuento estrategia;
    Carrito(EstrategiaDescuento e) { this.estrategia = e; }
    double total(double monto) { return estrategia.calcular(monto); }
}

